-- Phase 0: users, organizations (tenants), memberships and the audit log.
-- Conventions: UUID keys generated by the application (UUIDv7), timestamptz in UTC,
-- snake_case names, text enums guarded by CHECK constraints, optimistic concurrency via xmin.

CREATE TABLE users (
    id            uuid        PRIMARY KEY,
    issuer        text        NOT NULL,
    subject       text        NOT NULL,
    email         text        NOT NULL,
    display_name  text        NOT NULL,
    created_at    timestamptz NOT NULL,
    last_seen_at  timestamptz NOT NULL,
    CONSTRAINT uq_users_identity UNIQUE (issuer, subject),
    CONSTRAINT ck_users_email_lower CHECK (email = lower(email))
);

CREATE INDEX ix_users_email ON users (email);

CREATE TABLE organizations (
    id                   uuid        PRIMARY KEY,
    name                 text        NOT NULL CHECK (char_length(name) BETWEEN 2 AND 120),
    slug                 text        NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(slug) BETWEEN 3 AND 63),
    default_time_zone    text        NOT NULL,
    created_by           uuid        NOT NULL REFERENCES users (id),
    created_at           timestamptz NOT NULL,
    membership_revision  integer     NOT NULL DEFAULT 0,
    CONSTRAINT uq_organizations_slug UNIQUE (slug)
);

CREATE TABLE organization_members (
    id               uuid        PRIMARY KEY,
    organization_id  uuid        NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    user_id          uuid        NOT NULL REFERENCES users (id),
    role             text        NOT NULL CHECK (role IN ('Owner', 'Admin', 'Editor', 'Reviewer', 'Viewer')),
    created_at       timestamptz NOT NULL,
    CONSTRAINT uq_organization_members_user UNIQUE (organization_id, user_id)
);

CREATE INDEX ix_organization_members_user ON organization_members (user_id);

CREATE TABLE audit_logs (
    id               uuid        PRIMARY KEY,
    organization_id  uuid        NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    actor_id         uuid        NULL REFERENCES users (id),
    entity_type      text        NOT NULL,
    entity_id        uuid        NOT NULL,
    action           text        NOT NULL,
    diff_json        jsonb       NOT NULL DEFAULT '{}'::jsonb,
    trace_id         text        NULL,
    occurred_at      timestamptz NOT NULL
);

-- Keyset pagination: newest first within an organization.
CREATE INDEX ix_audit_logs_org_time ON audit_logs (organization_id, occurred_at DESC, id DESC);
CREATE INDEX ix_audit_logs_entity ON audit_logs (organization_id, entity_type, entity_id);

-- The audit log is append-only: block updates at the database level. Deletes are left to
-- retention/erasure jobs and organization deletion (ON DELETE CASCADE).
CREATE FUNCTION audit_logs_block_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_logs is append-only';
END;
$$;

CREATE TRIGGER trg_audit_logs_no_update
    BEFORE UPDATE ON audit_logs
    FOR EACH ROW EXECUTE FUNCTION audit_logs_block_mutation();
